const body = $input.first().json.body;
const actions = { 'process_ticket.submitted': 'notify_approver', 'process_ticket.approved': 'sync_approved_ticket' };
if (!body || !Object.hasOwn(actions, body.event) || typeof body.request_id !== 'string' || body.event_id !== `${body.request_id}:${body.event}` || !/^WO-\d{6,}$/.test(body.ticket_number ?? '')) throw new Error('Invalid ticket event');
return [{ json: { event_id: body.event_id, accepted: true, mode: 'simulation', action: actions[body.event], ticket: body } }];
